WFJ.Data.add("gossip", {
  ["f204c3e3dd6f0f9f"] = { "Che attraverso la conoscenza possiamo trovare la salvezza.", "." },
  ["f20694ae5193d82f"] = { "No, qui fuori non c'è nessuno che possa insegnarti l'erbalismo. Credo però che avrai più fortuna a ⟦Ironforge=Forgiardente⟧.", "." },
  ["f20c6bf3f69ba5c2"] = { "La tua prossima scelta ti attende.\n\nSenza l'aiuto di nessuno hai sconfitto una bestia terribile che devastava le campagne, prendendone l'orecchio come trofeo. In seguito vieni a sapere che il tuo signore aveva offerto una ricompensa per la morte della bestia, e che un cavaliere gentile ma indigente, che sai cercare di mantenere una famiglia con mezzi miseri, rivendica l'uccisione come propria. Tu non hai alcun bisogno di denaro, ma sai che il cavaliere indigente mente per il proprio tornaconto.\n\nFa' la tua scelta.", "." },
  ["f20f51cff967419e"] = { "La prossima volta che vai nel ⟦Molten Core=Nucleo Ardente⟧, uccidi un Signore del Fuoco per me, d'accordo?", "." },
  ["f214ae08700ba59c"] = { "Qualcosa affligge questa torre. Una malattia mi ha colpito, e anche gli altri dipendenti della S.P.R. & Co. che lavorano nella torre o nei dintorni si sono ammalati.\n\nGiusto la settimana scorsa, due delle nostre sentinelle sono morte, solo per tornare subito in vita come automi senza mente!\n\nLa forza vitale sta abbandonando il mio corpo. Sento che sto perdendo il controllo. Impulsi che prendono il sopravvento... Impulsi malvagi... *Fizzule si dà uno schiaffo in faccia* Non ancora... Ascolta... La mia è una posizione di potere. Questa posizione mi dà accesso ad alcune informazioni riservate.", "." },
  ["f22b09f69dad6e25"] = { "Quante altre provviste servono per il prossimo potenziamento?", "." },
  ["f23632f3a7418364"] = { "Ti... spezzo!!", "." },
  ["f239d1653c12f341"] = { "Ci saranno fuochi d'artificio per tutta la notte. Dalle sei di sera fino all'alba, il cielo sopra la ⟦Booty Bay=Baia del Bottino⟧ sarà in fiamme!", "." },
  ["f23b297fc40942a9"] = { "Hai sentito?", "." },
  ["f2446035bbcd7948"] = { "Colti alla sprovvista? Come?", "." },
  ["f24d84dfa56071e9"] = { "Se preparo una collezione di doni, cosa ne devo fare?", "." },
  ["f24df3268ade72d7"] = { "Salute. Insegno agli stregoni, e tu sei <uno/una> <stregone/strega>.", "." },
  ["f253e6280e634fe6"] = { "Fruga tra queste macerie.", "." },
  ["f25602a6ef6d63f2"] = { "Traghetto di Rut'theran", "." },
  ["f25d534588041f4b"] = { "La tua esistenza è riconosciuta. <La reliquia si sbriciola. La testa ti pulsa di una saggezza appena acquisita. Qualcosa di malvagio si annida nel cuore della montagna.>", "." },
  ["f2601a188e85a3a9"] = { "Non hai saputo proteggermi dalle scimmie!", "." },
  ["f2625ab41c02e99c"] = { "Il mastro pescatore Bassbait ha fatto popolare queste acque di tastyfish di alta qualità per poter tenere il suo torneo.\n\nUna volta che avrà il suo vincitore, ti darò dell'argento per ogni cinque tastyfish che mi porterai!", "." },
  ["f2682c8eb0c12119"] = { "Ancora nessun segno del 2° Battaglione da ⟦Stormwind=Roccavento⟧. Arrivano rapporti di movimenti dei Mantombroso a nord-est.", "." },
  ["f2940753156e7a9c"] = { "Dovresti dare un'occhiata a ⟦Ironforge=Forgiardente⟧, se hai deciso di dedicarti all'incantamento. Mi pare di aver visto una bottega vicino al maestro dei grifoni, l'ultima volta che ci ho fatto un salto.", "." },
  ["f29481b271e7168e"] = { "Intrusi! Uccideteli!", "." },
  ["f29526498b7ad9ae"] = { "<Un/Una> <ladro/ladra>? Mmm... beh, ho sentito che Keryn Sylvius frequenta quei tipi loschi. Potresti parlarle e vedere cosa riesci a scoprire.", "." },
  ["f2a025fb09f27ec5"] = { "Grazie per le informazioni, Frankal.", "." },
  ["f2aabbc879eca6c2"] = { "Puoi togliermi di dosso questo {name}?", "." },
  ["f2ac2e7a2e998721"] = { "⟦Hearthglen=Valsalda⟧?? Ma...", "." },
  ["f2b1a9bed317c67d"] = { "Nessuna fortuna con il disertore del ⟦Twilight's Hammer=Martello del Crepuscolo⟧? Perlustra a fondo le montagne a sud-est. Girano molte voci su un misterioso eremita che vive lassù.", "." },
  ["f2b66637298fb216"] = { "Solo uno sciocco entra ignaro in un covo di ladri. E quello sciocco raramente ne esce...", "." },
  ["f2b6b9563f585a9f"] = { "Che ne faremo di loro, padrone? Ormai non ci servono più a nulla.", "." },
  ["f2b7a19629f389c3"] = { "Buona idea!", "." },
  ["f2ba50e460d61f41"] = { "Finalmente capimmo da dove venivano le urla. Il ⟦The Butcher=Macellaio⟧ ci espose a un dolore che non sapevamo potesse esistere. Ci usò in innumerevoli esperimenti, nel tentativo di creare una piaga.\n\nI giorni divennero settimane. Saremmo morti il primo giorno, se quel bastardo crudele non ci avesse tenuti in vita con la magia.", "." },
  ["f2bebf21fc7e5de1"] = { "Non così in fretta, <bello/bella>... Non affiderò le redini di un possente montone da sella a chi non si è dimostrato alleato dei nani di ⟦Ironforge=Forgiardente⟧. Quando la tua reputazione con ⟦Ironforge=Forgiardente⟧ sarà Amichevole, ti mostrerò volentieri le varietà di montoni che ho in vendita.", "." },
  ["f2bf08e26cac0b31"] = { "Orribile.", "." },
  ["f2c1bdc31a48e0ce"] = { "Vorrei andare sul campo di battaglia.", "." },
  ["f2cd7f411abb6cd3"] = { "Insegnami a creare e applicare una ⟦Heavy Mageweave Bandage=Benda Pesante di Telamagica⟧, dottore.", "." },
  ["f2d068dcaeabeb98"] = { "Wow! Questi barili sono pieni di roba forte! Mi fanno volare fuori dagli stivali!", "." },
  ["f2d6eb042f6cc7a3"] = { "Il banditore di ⟦Southshore=Riva del Sud⟧ si porta una mano alla nuca e spalanca gli occhi.", "." },
  ["f2de8f5c37349aad"] = { "E per i nostri dèi?", "." },
  ["f2e24daade4d2295"] = { "Molthor vede tutto, {race}.", "." },
  ["f2f72e3b626a61ef"] = { "La ⟦Bluegill Marsh=Palude dei Branchiazzurra⟧, a nord di ⟦Menethil Harbor=Porto di Menethil⟧ nelle ⟦Wetlands=Paludi Grigie⟧, custodisce molti forzieri chiusi a chiave, portati a riva dai relitti al largo.", "." },
  ["f2fdef105d3694ae"] = { "Quant'è stato facile manipolarti perché recuperassi l'ultima pietra di Suntara da quegli imbecilli del ⟦Twilight's Hammer=Martello del Crepuscolo⟧.", "." },
  ["f2fe80590303ab7b"] = { "Grazie a tutti. Tornerò fra una settimana circa.", "." },
})
